import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Create the scene from the source file
const root = createScene();

// Apply -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
const exportRoot = new THREE.Group();
exportRoot.rotation.x = -Math.PI / 2;
exportRoot.add(root);

// Update all world matrices before processing
exportRoot.updateMatrixWorld(true);

// Expand InstancedMesh objects into individual Mesh objects so OBJExporter can handle them.
// OBJExporter.traverse only processes child.isMesh but doesn't read instanceMatrix.
function expandInstancedMeshes(obj) {
  const replacements = [];

  obj.traverse((child) => {
    if (child.isInstancedMesh) {
      replacements.push(child);
    }
  });

  for (const instMesh of replacements) {
    const parent = instMesh.parent;
    const count = instMesh.count;
    const geo = instMesh.geometry;
    const mat = instMesh.material;

    for (let i = 0; i < count; i++) {
      const m = new THREE.Matrix4();
      instMesh.getMatrixAt(i, m);

      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = instMesh.name + '_' + i;
      // Apply the instance transform and the instanced mesh's own world matrix
      // But since the mesh will be added to the same parent, we need only the instance-local transform
      mesh.applyMatrix4(m);
      parent.add(mesh);
    }

    parent.remove(instMesh);
  }
}

// Handle negative scales (mirrored geometry) by flipping face winding.
// When a mesh has a negative determinant in its world matrix, faces appear inverted.
// We need to flip the index buffer for those meshes so normals point correctly.
function fixMirroredGeometry(obj) {
  obj.updateMatrixWorld(true);

  obj.traverse((child) => {
    if (child.isMesh) {
      const det = child.matrixWorld.determinant();
      if (det < 0) {
        // Clone geometry to avoid mutating shared geometry
        const geom = child.geometry.clone();
        const index = geom.getIndex();
        if (index) {
          const arr = index.array.slice();
          for (let i = 0; i < arr.length; i += 3) {
            const tmp = arr[i];
            arr[i] = arr[i + 2];
            arr[i + 2] = tmp;
          }
          geom.setIndex(new THREE.BufferAttribute(arr, 1));
        }
        // Also flip normals
        const normals = geom.getAttribute('normal');
        if (normals) {
          const nArr = normals.array.slice();
          for (let i = 0; i < nArr.length; i++) {
            nArr[i] = -nArr[i];
          }
          geom.setAttribute('normal', new THREE.BufferAttribute(nArr, 3));
        }
        child.geometry = geom;
      }
    }
  });
}

expandInstancedMeshes(exportRoot);
exportRoot.updateMatrixWorld(true);
fixMirroredGeometry(exportRoot);
exportRoot.updateMatrixWorld(true);

// Export using OBJExporter
const exporter = new OBJExporter();
const objData = exporter.parse(exportRoot);

// Write to output
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objData);

console.log(`OBJ exported to ${outputPath}`);
console.log(`File size: ${(fs.statSync(outputPath).size / 1024).toFixed(1)} KB`);

// Quick validation: count elements
const lines = objData.split('\n');
const vCount = lines.filter(l => l.startsWith('v ')).length;
const vnCount = lines.filter(l => l.startsWith('vn ')).length;
const fCount = lines.filter(l => l.startsWith('f ')).length;
const oCount = lines.filter(l => l.startsWith('o ')).length;
console.log(`Objects: ${oCount}, Vertices: ${vCount}, Normals: ${vnCount}, Faces: ${fCount}`);

